-- Preços da inauguração: reajuste de 11,12% arredondado para cima até a próxima dezena de centavos
-- (por 100 g nos itens a granel e por unidade nos demais). Substitui o arquivo reajuste-precos-inauguracao.sql.
-- Altera SOMENTE mn_products.sale_cents (e updated_at) dos produtos já salvos pelo painel.
-- Produtos nunca editados no painel usam o catálogo do código e já recebem o novo preço com a implantação.
-- Cada linha só muda se o preço gravado for o anterior ao reajuste ou o do reajuste sem arredondamento:
-- importar de novo não altera nada, e preços já mudados no painel ficam como estão.
-- Produtos criados no painel (custom-...) não estão incluídos: ajuste-os no próprio painel.
-- Granel: sale_cents fica em centavos por kg (a vitrine mostra por 100 g). Unidade: centavos por unidade.

START TRANSACTION;
SET @mn_agora = ROUND(UNIX_TIMESTAMP(NOW(3)) * 1000);

INSERT INTO mn_audit(event,entity_id,details,created_at) SELECT 'product.price_raise', id, CONCAT('{"previousPriceCents":', sale_cents, ',"priceCents":8670,"source":"preços da inauguração"}'), @mn_agora FROM mn_products WHERE id='prod-1' AND is_bulk=0 AND sale_cents IN (7799,8666);
UPDATE mn_products SET sale_cents=8670, updated_at=@mn_agora WHERE id='prod-1' AND is_bulk=0 AND sale_cents IN (7799,8666);
